// KeyCRM read-only sample: converts CRM API response into an aggregate.
// Do not pass raw CRM records, comments, phones or addresses to an LLM.
const response = $input.first()?.json ?? {};
const orders = Array.isArray(response.data) ? response.data : (Array.isArray(response) ? response : []);
const byStatus = {};
const bySource = {};
let sampleGrandTotal = 0;
let knownAmounts = 0;
const clientIds = new Set();
for (const o of orders) {
  const status = String(o.status_id ?? 'MISSING');
  const source = String(o.source_id ?? 'MISSING');
  byStatus[status] = (byStatus[status] ?? 0) + 1;
  bySource[source] = (bySource[source] ?? 0) + 1;
  const value = Number(o.grand_total);
  if (o.grand_total !== undefined && o.grand_total !== null && Number.isFinite(value)) {
    knownAmounts++; sampleGrandTotal += value;
  }
  if (o.client_id !== undefined && o.client_id !== null) clientIds.add(String(o.client_id));
}
return [{json:{
  kind: 'keycrm_orders_readonly_sample',
  generated_at_utc: new Date().toISOString(),
  sample_size: orders.length,
  max_requested: 50,
  page_requested: 1,
  is_complete_dataset: false,
  note: 'Only page 1 (at most 50 orders); NOT a full period, lifetime or revenue report. Currency, sale status, price interpretation and status/source labels require validation.',
  counts_by_status_id: byStatus,
  counts_by_source_id: bySource,
  distinct_client_ids_in_sample: clientIds.size,
  sample_grand_total_raw: knownAmounts ? Math.round(sampleGrandTotal * 100) / 100 : null,
  amount_fields_found: knownAmounts,
  pagination_metadata: response.meta ? {current_page:response.meta.current_page ?? null, last_page:response.meta.last_page ?? null, total:response.meta.total ?? null} : null,
  pii_removed_from_output:true
}}];
